#nullable enable // autogenerated

using MVZ2.Audios;
using PVZEngine;

namespace MVZ2.Localization
{
    public class ResourcePackMusicSource : IMusicSource
    {
        public ResourcePackMusicSource(NamespaceID mainTrack, NamespaceID? subTrack)
        {
            this.mainTrack = mainTrack;
            this.subTrack = subTrack;
        }
        public NamespaceID? GetMainTrack()
        {
            return mainTrack;
        }

        public NamespaceID? GetSubTrack()
        {
            return subTrack;
        }
        public NamespaceID mainTrack;
        public NamespaceID? subTrack;
    }
}
